{
  "originalFormula": "I = n \cdot A \cdot q \cdot v",
  "genericFormula": "I = n \cdot A \cdot q \cdot v",
  "description": "Esta fórmula representa a corrente elétrica em um condutor, onde a corrente é o fluxo de carga elétrica que passa por uma seção transversal do material em um determinado intervalo de tempo.",
  "concepts": [
    "Corrente elétrica",
    "Densidade de portadores de carga",
    "Área da seção transversal",
    "Carga elétrica",
    "Velocidade média dos portadores de carga"
  ],
  "symbols": [
    {
      "symbol": "I",
      "description": "Representa a corrente elétrica, que é a quantidade de carga que passa por um ponto em um circuito por unidade de tempo."
    },
    {
      "symbol": "n",
      "description": "Representa a densidade de portadores de carga, ou seja, o número de portadores de carga por unidade de volume no material."
    },
    {
      "symbol": "A",
      "description": "Representa a área da seção transversal do condutor, que é a área pela qual a corrente elétrica flui."
    },
    {
      "symbol": "q",
      "description": "Representa a carga elétrica de cada portador de carga, que é a quantidade de eletricidade que cada partícula transporta."
    },
    {
      "symbol": "v",
      "description": "Representa a velocidade média dos portadores de carga, que é a velocidade com que os portadores se movem através do condutor."
    }
  ]
}
